script.code:
// Classify every quotation line against the stored quotation. The child-table row `id`
// is the only stable handle -- line_index is positional and table_sqt has no fm_key.
// Mirrors code_cd_diff one level down, with one addition: price is in scope here, so a
// line whose money moved and whose quantity did not still produces a change.
//
// A literal string in a workflow-node's body_params is evaluated by MVEL, and a value
// that collides with a builtin -- "append" does -- arrives as a function reference, not
// a string. The pass is discriminated by an int, which MVEL cannot resolve to anything.
const isAppend = Number({{workflowparams:passNo}}) === 2;
const prevRaw = {{workflowparams:prev_table_sqt}};
const nextRaw = {{workflowparams:next_table_sqt}};

const flat = (rows) =>
  (Array.isArray(rows) ? rows : []).flatMap((r) =>
    [r].concat(Array.isArray(r && r.children) ? r.children : [])
  );
const num = (v) => { const n = parseFloat(v); return isNaN(n) ? 0 : n; };
const sid = (v) => String(v === null || v === undefined ? "" : v);
const round3 = (v) => Math.round(num(v) * 1000) / 1000;
const QTY_EPS = 0.0005;
// Money is decimal(65,4), so it needs a tighter epsilon than quantity's 3dp.
const MONEY_EPS = 0.00005;

const prevLines = flat(prevRaw).filter((r) => r);
const nextLines = flat(nextRaw).filter((r) => r);

const prevById = {};
prevLines.forEach((r) => { if (r.id) prevById[sid(r.id)] = r; });
const nextById = {};
nextLines.forEach((r) => { if (r.id) nextById[sid(r.id)] = r; });

const changes = [];
const materialIds = [];
const pushMat = (m) => {
  const s = sid(m);
  if (s && materialIds.indexOf(s) < 0) materialIds.push(s);
};

// Every money input ConvertToSO maps onto the SO line. Carried whole, so code_sqtcd_plan
// can restate the order line without re-reading the quotation.
const money = (r) => ({
  price: num(r.unit_price),
  discount: num(r.sqt_discount),
  discountUom: sid(r.sqt_discount_uom_id),
  taxPreference: r.sqt_taxes_rate_id ? sid(r.sqt_taxes_rate_id) : null,
  taxPercent: num(r.sqt_tax_rate_percent),
  taxInclusive: Number(r.sqt_tax_inclusive) === 1 ? 1 : 0
});

const moneyMoved = (a, b) => {
  const x = money(a);
  const y = money(b);
  return Math.abs(x.price - y.price) > MONEY_EPS ||
    Math.abs(x.discount - y.discount) > MONEY_EPS ||
    x.discountUom !== y.discountUom ||
    sid(x.taxPreference) !== sid(y.taxPreference) ||
    Math.abs(x.taxPercent - y.taxPercent) > MONEY_EPS ||
    x.taxInclusive !== y.taxInclusive;
};

const entry = (row, kind, base) => ({
  sqtLineId: sid(row.id),
  kind: kind,
  prevQty: round3(base.quantity),
  nextQty: round3(row.quantity),
  prevItem: sid(base.material_id),
  nextItem: sid(row.material_id),
  prevUom: sid(base.sqt_order_uom_id),
  nextUom: sid(row.sqt_order_uom_id),
  desc: sid(row.sqt_desc),
  moreDesc: sid(row.more_desc),
  furtherDesc: sid(row.further_description),
  itemCode: sid(row.material_name),
  lineIndex: sid(row.line_index),
  shippingDate: row.expected_shipment_date || null,
  // SQT_Convert_SO DOES carry a bundle over as a parent with its items under
  // `children`. It is still flagged and refused in code_sqtcd_plan, for a different
  // reason: a bundle parent's money is a rollup of its items, and the recompute there
  // is a plain qty x price per row. SOCalculation has a separate bundle path that is
  // not replicated here.
  isBundle: (Array.isArray(row.children) && row.children.length) || row.item_bundle_id ? 1 : 0,
  money: money(row),
  moneyChanged: moneyMoved(base, row) ? 1 : 0
});

const addLine = (r) => {
  const e = entry(r, "added", r);
  e.prevQty = 0;
  e.prevItem = "";
  e.moneyChanged = 1;
  changes.push(e);
  pushMat(r.material_id);
};

if (isAppend) {
  // Pass 2. next_table_sqt is the PERSISTED quotation, so a row added during this save
  // now carries the platform id it did not have when pass 1 ran -- and that id is what
  // gets stamped on the new order line as sqt_line_id. Only additions are looked at
  // here; everything else was already applied by pass 1.
  nextLines.forEach((r) => {
    if (!r.id || prevById[sid(r.id)] || !r.material_id) return;
    addLine(r);
  });
} else {

nextLines.forEach((r) => {
  // No id, or no stored row behind it: added during THIS save, so it has no id yet and
  // nothing to append against. Pass 2 picks it up once the quotation is written.
  const before = r.id ? prevById[sid(r.id)] : null;
  if (!before) return;
  const prevItem = sid(before.material_id);
  const nextItem = sid(r.material_id);
  if (prevItem !== nextItem) {
    changes.push(entry(r, "swap", before));
    pushMat(nextItem);
    pushMat(prevItem);
  } else if (sid(before.sqt_order_uom_id) !== sid(r.sqt_order_uom_id)) {
    // Same item, different unit. The order quantity may not have moved at all, but the
    // base quantity did, so SO_CASCADE restates the delivery across the ratio.
    changes.push(entry(r, "uom", before));
    pushMat(nextItem);
  } else if (Math.abs(round3(r.quantity) - round3(before.quantity)) > QTY_EPS) {
    changes.push(entry(r, "qty", before));
    pushMat(nextItem);
  } else if (moneyMoved(before, r)) {
    changes.push(entry(r, "price", before));
    pushMat(nextItem);
  }
});

// Absent from the submitted array = removed. code_node_CO6q7Vm4 already dropped blank
// and zero-quantity rows upstream, so a zeroed line reaches us as a removal.
prevLines.forEach((r) => {
  if (!r.id || nextById[sid(r.id)]) return;
  const e = entry(r, "removed", r);
  e.nextQty = 0;
  e.nextItem = "";
  changes.push(e);
  pushMat(r.material_id);
});

}

// An empty `in` / `equalAny` matches every row, so never hand a search a bare [].
// The sentinel must be NUMERIC: the id column it reaches is BigInt, and "0" is never a
// real snowflake id.
const added = changes.filter((c) => c.kind === "added");

return {
  changes: changes,
  changeCount: changes.length,
  addedCount: added.length,
  removedCount: changes.filter((c) => c.kind === "removed").length,
  // Handed to SQT_Convert_SO's "lines" mode, which owns the SQT->SO line mapping.
  // Empty in pass 1 by construction: a row added during this save has no id yet.
  addedLineIds: added.map((c) => c.sqtLineId).filter((x) => x),
  materialIds: materialIds.length ? materialIds : ["0"],
  emptyList: []
};

// Pick the one live sales order this quotation edit can act on. Thin on purpose: the
// draft-delivery and draft-invoice searches below need a concrete so_id to filter on,
// while every refusal -- including "more than one order" -- is worded in
// code_sqtcd_plan, so the messages live in one place.
const sosRaw = {{node:search_sqtcd_sos.data.data}};
const list = Array.isArray(sosRaw) ? sosRaw : (sosRaw ? [sosRaw] : []);
const live = list.filter((s) => s && String(s.so_status || "") !== "Cancelled");

// "0" is never a real snowflake id, so when there is no single order to act on the
// searches match nothing -- rather than matching everything, the way an empty `in` does.
return {
  soId: live.length === 1 ? String(live[0].id) : "0",
  liveCount: live.length
};

// Decide what this quotation edit does to its sales order, and refuse in words when it
// cannot be done. Everything delivery-shaped -- reducing below what is already picked, a
// unit change on a line a picking plan holds -- is deliberately NOT re-implemented here.
// SO_CASCADE already produces better messages for those, and they bubble up through
// SO_SAVE as 406 / 413 / 414. Never write a second version of one of its refusals.
// A literal string in a workflow-node's body_params is evaluated by MVEL, and a value
// that collides with a builtin arrives as a function reference. The pass is an int.
const isAppend = Number({{workflowparams:passNo}}) === 2;
const changes = {{node:code_sqtcd_diff.data.changes}} || [];
// Order lines built by SQT_Convert_SO's "lines" mode -- the single owner of the
// SQT->SO column mapping. Empty in pass 1, where added rows have no id yet.
const mappedRaw = {{node:wf_sqtcd_maplines.data.data}};
const sosRaw = {{node:search_sqtcd_sos.data.data}};
const itemsRaw = {{node:search_sqtcd_items.data.data}};
const approvalRaw = {{node:get_sqtcd_approval.data.data}};
const draftGdRaw = {{node:search_sqtcd_draftgd.data.data}};
const draftSiRaw = {{node:search_sqtcd_draftsi.data.data}};

const asArray = (v) => (Array.isArray(v) ? v : v ? [v] : []);
// Row + its bundle items: a bundle's items are order lines in their own right and carry
// their own sqt_line_id.
const flat = (rows) =>
  asArray(rows).flatMap((r) => [r].concat(Array.isArray(r && r.children) ? r.children : []));
const num = (v) => { const n = parseFloat(v); return isNaN(n) ? 0 : n; };
const sid = (v) => String(v === null || v === undefined ? "" : v);
const round3 = (v) => Math.round(num(v) * 1000) / 1000;
// SOCalculation's rounder, copied exactly. The order has to stay arithmetically
// consistent with what the browser would compute for the same lines, because the next
// person to touch a row recomputes only that row and sums the rest as stored.
const roundPrice = (v) => parseFloat(parseFloat(v || 0).toFixed(4));

const block = (msg) => ({
  blocked: 1, blockCode: "406", blockSignal: 1, blockKind: "block",
  blockMessage: msg, soPayloads: [], emptyList: []
});

// ---- which order, and may we touch it at all --------------------------------------
const sos = asArray(sosRaw).filter((s) => s && sid(s.so_status) !== "Cancelled");
// No live order behind this quotation -- it was never converted, or the order it produced
// was cancelled. Nothing downstream to update, so this is a no-op and NOT a refusal:
// an ordinary Issued quotation is edited through this same path and must not be blocked.
if (!sos.length) {
  return {
    blocked: 0, blockCode: "200", blockSignal: 0, blockKind: "", blockMessage: "",
    soPayloads: [], emptyList: []
  };
}
if (sos.length > 1) {
  return block("This quotation has been converted to more than one sales order (" +
    sos.map((s) => sid(s.so_no)).join(", ") +
    ").<br><br>Edit those sales orders one at a time.");
}
const so = JSON.parse(JSON.stringify(sos[0]));
const soNo = sid(so.so_no) || sid(so.id);
const soStatus = sid(so.so_status);

// B4
if (soStatus === "Completed" || soStatus === "Cancelled") {
  return block(soNo + " is " + soStatus + " and can no longer be changed.");
}

// B13 -- SO_SAVE runs CHECK_REQUIRED_FIELD over these and ends 400 if one is blank.
// Pre-empted here so the user gets a sentence instead of a validation dump.
const REQUIRED = [
  ["so_no", "Sales Order Number"], ["customer_name", "Customer"],
  ["plant_name", "Plant"], ["so_date", "Sales Order Date"],
  ["so_payment_term", "Payment Term"], ["acc_integration_type", "Accounting Integration"]
];
const missing = REQUIRED.filter((f) => !sid(so[f[0]])).map((f) => f[1]);
if (missing.length) {
  return block(soNo + " is missing " + missing.join(", ") +
    ", so it cannot be saved automatically.<br><br>Open that sales order and complete it first.");
}
if (!asArray(so.table_so).length) {
  return block(soNo + " has no line items, so it cannot be saved automatically.");
}

// B6 -- if_6MfJ2Oif has no already-created guard: every re-save of an Issued auto-invoice
// order raises another invoice.
if (Number(so.auto_si) === 1 && soStatus === "Issued") {
  return block(soNo + " raises its invoice automatically. Saving it again from here would " +
    "create a second invoice.<br><br>Edit that sales order directly.");
}

// B7 -- an approval slot suspends the run waiting on a person, so a cascade that reaches
// one never returns. so_convert fires on EVERY order carrying a quotation id, which is
// exactly this population. The other triggers cannot fire from here: so_issued needs the
// 'issued' doc-number sentinel and so_credit_limit needs cl_result 'override', neither of
// which the payload we build can produce.
const approval = asArray(approvalRaw)[0] || approvalRaw || null;
let approvalRules = (approval && approval.approval_rules) || [];
if (typeof approvalRules === "string") {
  try { approvalRules = JSON.parse(approvalRules); } catch (e) { approvalRules = []; }
}
const soRule = asArray(approvalRules).find((r) => r && sid(r.document_type) === "SO") || null;
if (soRule && Number(soRule.so_convert) === 1) {
  return block("Sales orders converted from a quotation need approval in this organisation, " +
    "so the change cannot be pushed into " + soNo + " automatically.<br><br>Edit that sales order directly.");
}

// B5 -- if_ZprBCz35 ends 404 on these, and answering that 404 deletes the documents. A
// quotation edit must never do that silently, so it refuses and names them instead.
const draftGds = asArray(draftGdRaw).filter((g) => g && sid(g.gd_status) === "Draft");
const draftSis = asArray(draftSiRaw).filter((s) => s && sid(s.si_status) === "Draft");
if (draftGds.length || draftSis.length) {
  const names = draftGds.map((g) => sid(g.delivery_no)).concat(draftSis.map((s) => sid(s.si_no)));
  return block(soNo + " has a draft document waiting on it (" + names.join(", ") +
    ").<br><br>Complete or delete it, then edit the quotation again.");
}

// ---- pair each changed quotation line to its order line ---------------------------
const soLines = asArray(so.table_so);
const soLineBySqtLine = {};
// Flattened: a bundle's items are order lines in their own right and carry their own
// sqt_line_id. Header totals below still iterate top level only, the way SOCalculation
// does, because a bundle parent already carries its items' rollup.
flat(soLines).forEach((r) => {
  if (r && sid(r.sqt_line_id)) soLineBySqtLine[sid(r.sqt_line_id)] = r;
});

const items = asArray(itemsRaw);
const itemById = {};
items.forEach((i) => { if (i && i.id) itemById[sid(i.id)] = i; });

const getPackingDetail = (tpd, uom) =>
  (!Array.isArray(tpd) || !tpd.length || !uom) ? null : (tpd.find((c) => c.uom_id === uom) || null);
const getBaseQty = (tuc, uom) => {
  if (!Array.isArray(tuc) || !tuc.length || !uom) return 1;
  const c = tuc.find((x) => x.alt_uom_id === uom);
  return c && c.base_qty ? c.base_qty : 1;
};

const moneyChangedAnywhere = changes.some((c) => Number(c.moneyChanged) === 1);

// B10 -- a posted order whose amounts move leaves the accounting document behind, and
// if__zXmoKQP will not re-post something already Posted.
if (moneyChangedAnywhere && sid(so.posted_status) === "Posted") {
  return block(soNo + " has already been posted to accounting. Changing its amounts would " +
    "leave that posting out of date.<br><br>Reverse the posting first.");
}

const touched = [];          // row references this edit recomputes
const dropped = [];          // row references this edit removes
const priceFailures = [];

// Min/max price is what CHECK_APPROVAL polices, and outside those bounds the order
// either ends 402 or suspends on an approval slot. Same predicate and same wording it
// uses, so the user reads the text the sales order page would have shown.
const checkPrice = (lineNo, price, minRaw, maxRaw) => {
  const min = parseFloat(minRaw);
  if (!(minRaw == null || minRaw === "" || isNaN(min) || min === 0) && num(price) < min) {
    priceFailures.push("Line " + lineNo + ": Unit Price " + num(price) + " is below Min Price " + minRaw);
  }
  const max = parseFloat(maxRaw);
  if (!(maxRaw == null || maxRaw === "" || isNaN(max) || max === 0) && num(price) > max) {
    priceFailures.push("Line " + lineNo + ": Unit Price " + num(price) + " exceeds Max Price " + maxRaw);
  }
};

if (isAppend) {
  // ---- pass 2: rows added to the quotation join the order -------------------------
  let mapped = mappedRaw;
  if (typeof mapped === "string") {
    try { mapped = JSON.parse(mapped); } catch (e) { mapped = []; }
  }
  mapped = asArray(mapped);
  const wanted = {};
  changes.forEach((c) => { if (c.kind === "added") wanted[sid(c.sqtLineId)] = c; });

  const toAppend = mapped.filter((l) => l && wanted[sid(l.sqt_line_id)]);
  if (!toAppend.length) {
    return {
      blocked: 0, blockCode: "200", blockSignal: 0, blockKind: "", blockMessage: "",
      soPayloads: [], emptyList: []
    };
  }

  for (const l of toAppend) {
    const ch = wanted[sid(l.sqt_line_id)];
    const label = sid(ch.itemCode) || sid(ch.desc) || ("line " + sid(ch.lineIndex));
    if (Number(ch.isBundle) === 1) {
      return block("Item bundles are priced as a whole, so " + label +
        " cannot be added to " + soNo + " automatically.<br><br>Add it on that sales order directly.");
    }
    checkPrice(sid(ch.lineIndex) || "?", l.so_item_price, l.min_price, l.max_price);
    // A brand new order line owes nothing to anyone yet.
    l.delivered_qty = 0;
    l.planned_qty = 0;
    l.invoice_qty = 0;
    l.line_status = soStatus === "Draft" ? "Draft" : "Issued";
    soLines.push(l);
    touched.push(l);
  }
} else {
  // ---- pass 1: rows that already exist on both sides -------------------------------
  for (const ch of changes) {
    const label = sid(ch.itemCode) || sid(ch.desc) || ("line " + sid(ch.lineIndex));

    // B12 -- a bundle IS on the order, as a parent with its items under `children`, but
    // its parent line's money is a rollup of the items rather than qty x price. The
    // recompute below would restate it as a plain line and quietly change the total.
    if (Number(ch.isBundle) === 1) {
      return block("Item bundles are priced as a whole, so the change to " + label +
        " cannot be restated on the sales order automatically.<br><br>Edit " + soNo + " directly.");
    }

    // B2 -- the pairing column only exists on orders converted after it shipped.
    const line = soLineBySqtLine[sid(ch.sqtLineId)];
    if (!line) {
      return block(soNo + " was created before quotation lines were linked to order lines " +
        "individually, so the change to " + label + " cannot be matched to it.<br><br>" +
        "Edit that sales order directly.");
    }

    // These three counters are written by the delivery, the plan and the invoice, and
    // they sit on the order line already fetched -- so the common refusals are answered
    // here in one hop instead of after SO_SAVE and SO_CASCADE have both been started.
    // Reconciling the delivery's OWN lines stays SO_CASCADE's job: it owns that
    // arithmetic and its messages name the delivery.
    const delivered = round3(line.delivered_qty);
    const planned = round3(line.planned_qty);
    const invoiced = round3(line.invoice_qty);

    if (ch.kind === "removed") {
      if (delivered > 0 || invoiced > 0) {
        return block(label + " has already been " +
          (delivered > 0 ? "delivered (" + delivered + ")" : "invoiced (" + invoiced + ")") +
          " on " + soNo + ", so it cannot be removed from the quotation.<br><br>" +
          "Cancel or credit that first, or edit the sales order directly.");
      }
      if (planned > 0) {
        return block(label + " is planned on a picking plan for " + soNo +
          ", so it cannot be removed from the quotation.<br><br>" +
          "Cancel that picking plan first, or edit the sales order directly.");
      }
      dropped.push(line);
      continue;
    }

    // A reduction below what has already gone out is refused the same way, before two
    // more workflows are started to say so.
    if (round3(ch.nextQty) + 0.0005 < delivered) {
      return block(label + " has already been delivered " + delivered + " on " + soNo +
        ". The quantity cannot be reduced to " + round3(ch.nextQty) + ".");
    }
    if (Number(ch.moneyChanged) === 1 && invoiced > 0) {
      return block(soNo + " has already been invoiced, so the price on " + label +
        " can no longer be changed.<br><br>Credit the invoice first, or edit that sales order directly.");
    }

    // B9 -- header-level invoicing, for orders invoiced without a per-line counter.
    if (Number(ch.moneyChanged) === 1 &&
        (sid(so.si_status) === "Partially Invoiced" || sid(so.si_status) === "Fully Invoiced")) {
      return block(soNo + " has already been invoiced, so the price on " + label +
        " can no longer be changed.<br><br>Credit the invoice first, or edit that sales order directly.");
    }

    const m = ch.money || {};
    checkPrice(sid(ch.lineIndex) || "?", m.price, line.min_price, line.max_price);

    // ---- the patch itself ----
    line.so_quantity = round3(ch.nextQty);
    line.so_item_uom = sid(ch.nextUom) || line.so_item_uom;
    line.item_name = sid(ch.nextItem) || line.item_name;
    line.item_id = sid(ch.itemCode) || line.item_id;
    line.so_desc = ch.desc;
    line.more_desc = ch.moreDesc;
    line.further_description = ch.furtherDesc;
    if (ch.shippingDate) line.so_shipping_date = ch.shippingDate;
    line.so_item_price = roundPrice(m.price);
    line.so_discount = num(m.discount);
    line.so_discount_uom = sid(m.discountUom);
    line.so_tax_preference = m.taxPreference || null;
    // so_tax_percentage is an int column -- never a toFixed string.
    line.so_tax_percentage = Math.round(num(m.taxPercent));
    line.so_tax_inclusive = Number(m.taxInclusive) === 1 ? 1 : 0;

    // A different item, or the same item counted in a different unit, invalidates the
    // packing and weight ratios GDheadWorkflow derives packing_qty and net_weight from.
    if (ch.kind === "swap" || ch.kind === "uom") {
      const item = itemById[sid(ch.nextItem)];
      if (!item) {
        return block("The item on " + label + " could not be read, so " + soNo +
          " cannot be updated.<br><br>Edit that sales order directly.");
      }
      const uom = sid(ch.nextUom);
      const pd = getPackingDetail(item.table_packing_detail, uom);
      const packingConversion = (pd && pd.quantity) || 1;
      line.packing_uom = (pd && pd.packing_uom_id) || "";
      line.packing_conversion = parseFloat(packingConversion || 0).toFixed(3);
      line.weight_conversion =
        round3((Number(item.net_weight) || 0) * getBaseQty(item.table_uom_conversion, uom)).toFixed(3);
    }

    touched.push(line);
  }

  if (dropped.length) {
    const keep = soLines.filter((r) => dropped.indexOf(r) < 0);
    if (!keep.length) {
      return block("Removing that line would leave " + soNo +
        " with nothing on it.<br><br>Cancel the sales order instead.");
    }
    so.table_so = keep;
  }
}

if (priceFailures.length) {
  return block("The new price is outside the limits set on the item, so " + soNo +
    " cannot be updated automatically:<br><br>" + priceFailures.join("<br>") +
    "<br><br>Change the price, or edit that sales order directly.");
}

// ---- restate the money, SOCalculation's way ---------------------------------------
// A line this edit did not touch contributes its STORED figures, which is what makes an
// order built from more than one quotation safe: the other quotation's lines pass
// through untouched, exactly as the browser leaves them.
let totalGross = 0;
let totalDiscount = 0;
let totalTax = 0;
let totalAmount = 0;

// so.table_so, not soLines: a removal rebuilt the array, and an append pushed onto it.
// Top level only, the way SOCalculation sums -- a bundle parent already carries the
// rollup of its items.
asArray(so.table_so).forEach((row) => {
  if (!row) return;
  // Row references, not ids: an appended line has no id yet, so keying on one would put
  // every new line in the same bucket.
  if (touched.indexOf(row) < 0) {
    totalGross += roundPrice(row.so_gross);
    totalDiscount += roundPrice(row.so_discount_amount);
    totalTax += roundPrice(row.so_tax_amount);
    totalAmount += roundPrice(row.so_amount);
    return;
  }

  const quantity = num(row.so_quantity);
  const unitPrice = roundPrice(row.so_item_price);
  const grossValue = quantity * unitPrice;
  row.so_gross = roundPrice(grossValue);

  let discount = num(row.so_discount);
  let discountUOM = sid(row.so_discount_uom);
  if (discount > 0 && !discountUOM) {
    discountUOM = "Amount";
    row.so_discount_uom = "Amount";
  }
  let discountAmount = 0;
  if (discountUOM && discount !== 0) {
    if (discountUOM === "Amount") {
      discountAmount = roundPrice(discount);
    } else if (discountUOM === "%") {
      discountAmount = roundPrice((grossValue * discount) / 100);
    }
    // A discount bigger than the line is a data-entry slip; SOCalculation zeroes both.
    if (roundPrice(discountAmount) > roundPrice(grossValue)) {
      discountAmount = 0;
      row.so_discount = 0;
    }
  }
  row.so_discount_amount = roundPrice(discountAmount);

  const amountAfterDiscount = roundPrice(grossValue - discountAmount);
  const taxRate = num(row.so_tax_percentage);
  let taxAmount = 0;
  let finalAmount = amountAfterDiscount;
  if (taxRate) {
    const d = taxRate / 100;
    if (Number(row.so_tax_inclusive) === 1) {
      taxAmount = roundPrice(amountAfterDiscount - amountAfterDiscount / (1 + d));
      finalAmount = amountAfterDiscount;
    } else {
      taxAmount = roundPrice(amountAfterDiscount * d);
      finalAmount = amountAfterDiscount + taxAmount;
    }
  }
  row.so_tax_amount = roundPrice(taxAmount);
  row.so_amount = roundPrice(finalAmount);

  totalGross += roundPrice(grossValue);
  totalDiscount += roundPrice(discountAmount);
  totalTax += roundPrice(taxAmount);
  totalAmount += roundPrice(finalAmount);
});

so.so_total_gross = roundPrice(totalGross);
so.so_total_discount = roundPrice(totalDiscount);
so.so_total_tax = roundPrice(totalTax);
so.so_total = roundPrice(totalAmount);
// Only moves when a rate is actually set; an order with a blank rate keeps its stored
// MYR total rather than being zeroed.
if (num(so.exchange_rate)) {
  so.myr_total_amount = roundPrice(num(so.exchange_rate) * roundPrice(totalAmount));
}

// B11 -- if_C6bxfvdn ends 405 on a zero-total auto-invoice order, and a zero-total order
// is a mistake regardless.
if (roundPrice(totalAmount) <= 0) {
  return block("The change would leave " + soNo + " with a total of 0, so it was not applied.");
}

// ---- the payload SO_SAVE is handed ------------------------------------------------
// Built by patching the row as fetched, never by constructing a literal:
// update_node_Bw4VsiNH rewrites 142 header columns from whatever arrives here, and a
// column left out is blanked on a live order.
so.page_status = "Edit";
// code_node_X4j8BSXd redraws the document number when so_no is blank or previous_status
// is 'Draft'. The order already has its number, and this must not burn another.
so.previous_status = soStatus === "Draft" ? "" : soStatus;
// Non-blank, so the same node does not force the credit-limit path on. Never persisted:
// code_node_BtxYhPym blanks it again before the write.
so.need_cl = "not required";
so.create_si = sid(so.create_si) || "No";
// Temporary markers must never reach the write.
asArray(so.table_so).forEach((r) => { if (r) { delete r.__touched; } });
so.confirmPickReversal = {{workflowparams:confirmPickReversal}};
so.raiseGdQty = {{workflowparams:raiseGdQty}};

return {
  blocked: 0, blockCode: "200", blockSignal: 0, blockKind: "", blockMessage: "",
  soPayloads: [{ so_id: sid(so.id), so_no: soNo, allData: so }],
  emptyList: []
};

// Per-run redis namespace, so concurrent quotation saves never share an accumulator.
const sqtId = {{workflowparams:sqt_id}} || "";

return {
  unique: String(sqtId) + "_" + Date.now(),
};

const raw = {{node:get_sqtcd_res.data}};
let results = [];
if (raw) { results = typeof raw === "string" ? JSON.parse(raw) : raw; }
if (!Array.isArray(results)) results = [];

// SO_SAVE declares ONE response key, `data`, and puts two different payloads in it: a
// saved order carries so_id, a gate carries gateCode. Never test for a particular failure
// code -- the same reason code_cd_collect_gd does not: a refusal can arrive with none.
let payload = {{node:wf_sqtcd_so.data.data}};
if (typeof payload === "string") {
  try { payload = JSON.parse(payload); } catch (e) { payload = {}; }
}
if (!payload || typeof payload !== "object") payload = {};

const gateCode = String(payload.gateCode || "");
const savedId = String(payload.so_id || "");

results.push({
  doc: "SO",
  doc_no: {{node:loop_sqtcd_so.so_no}} || "",
  code: gateCode || (savedId ? "200" : ""),
  ok: !gateCode && savedId ? 1 : 0,
  // 414 (raise the delivery quantity) and 413 (reverse what is already picked) are
  // questions the delivery asked, relayed up through the order. Both return before
  // anything is written, so they are relayed rather than reported as failures.
  confirm: gateCode === "413" || gateCode === "414" ? 1 : 0,
  gateCode: gateCode,
  message: String(payload.message || ""),
  note: String(payload.pickingReversalNote || "")
});

return { results: results };

const isAppend = Number({{workflowparams:passNo}}) === 2;
const raw = {{node:get_sqtcd_res_final.data}};
let results = [];
if (raw) { results = typeof raw === "string" ? JSON.parse(raw) : raw; }
if (!Array.isArray(results)) results = [];

const ok = results.filter((r) => r.ok === 1);
const raise = results.filter((r) => r.gateCode === "414");
const reversal = results.filter((r) => r.gateCode === "413");
const bad = results.filter((r) => r.ok !== 1 && r.confirm !== 1);
const note = ok.map((r) => r.note).filter((n) => n).join("<br><br>");
const joined = (rows) => rows.map((r) => r.message).filter((m) => m).join("<br><br>");

// A question outranks the work: the user answers, the quotation save re-runs whole, and
// an order or delivery already updated is a no-op the second time round. Raise is asked
// before reversal, the same order SOsaveWorkflow's three gate branches test in.
if (raise.length) {
  return {
    code: "414", message: joined(raise), blockKind: "confirmRaise", blockSignal: 3,
    pickingReversalNote: "", appliedSummary: results
  };
}
if (reversal.length) {
  return {
    code: "413", message: joined(reversal), blockKind: "confirmReversal", blockSignal: 2,
    pickingReversalNote: "", appliedSummary: results
  };
}
if (!bad.length) {
  return {
    code: "200", message: "", blockKind: "", blockSignal: 0,
    pickingReversalNote: note, appliedSummary: results
  };
}

// Pass 1 runs ahead of update_node_ag4jFZch, so nothing of the quotation is written yet.
// Pass 2 runs after it, so it must never claim otherwise. The payload is rebuilt from the
// stored order on every attempt, so a retry converges rather than compounding.
const lead = isAppend
  ? "The quotation was saved, but the new line could not be added to " +
    (bad.map((r) => r.doc_no).filter((n) => n).join(", ") || "the sales order") + ":<br><br>"
  : ok.length
    ? "The quotation was not saved. " + ok.length +
      " linked sales order(s) were already updated (" + ok.map((r) => r.doc_no).join(", ") +
      ") and saving again will leave them as they are.<br><br>"
    : "The quotation was not saved.<br><br>";

const tail = isAppend ? "<br><br>Add that line on the sales order directly." : "";

return {
  code: "406",
  message: lead + bad.map((r) => (r.doc_no || r.doc) + ": " + (r.message || "failed")).join("<br>") + tail,
  blockKind: "block",
  blockSignal: 1,
  pickingReversalNote: note,
  appliedSummary: results
};
